from elftools.elf.elffile import ELFFile
f=open('/home/vboxuser/rev-analysis/extract/csirac/csirac.pd_linux','rb')
e=ELFFile(f)
print("sections:")
for s in e.iter_sections():
    print(f"  {s.name:20s} addr=0x{s['sh_addr']:08x} off=0x{s['sh_offset']:08x} size=0x{s['sh_size']:x} ({s['sh_size']})")
print("dynamic symbols (setup/class):")
for sec in e.iter_sections():
    from elftools.elf.sections import SymbolTableSection
    if isinstance(sec, SymbolTableSection):
        for sym in sec.iter_symbols():
            if sym.name and ('setup' in sym.name or 'csirac' in sym.name.lower() or 'new' in sym.name):
                print("  ",sym.name, hex(sym['st_value']), sym['st_size'])
PY

